# owner: platform
import unittest

from tests.support import data_file
from hourglass.timesheet import timesheet_lines
from hourglass.schedule import load_schedule
from hourglass.models import Shift, Span


def shift(worker, begin, finish, day="mon"):
    return Shift(worker, day, Span(begin, finish))


class TimesheetTests(unittest.TestCase):
    def test_busiest_first(self):
        lines = timesheet_lines([
            shift("Ana", 540, 600),
            shift("Ben", 540, 840),
            shift("Ana", 600, 660, "tue")
        ])
        self.assertEqual(lines, [
            "Ben: 1 shift, 5.0 hours",
            "Ana: 2 shifts, 2.0 hours"
        ])

    def test_one_decimal_place(self):
        lines = timesheet_lines([shift("Ana", 540, 620)])
        self.assertEqual(
            lines, ["Ana: 1 shift, 1.3 hours"]
        )

    def test_ties_sorted_by_name(self):
        lines = timesheet_lines([
            shift("Zed", 540, 600),
            shift("Amy", 540, 600)
        ])
        self.assertTrue(lines[0].startswith("Amy"))

    def test_empty_list(self):
        with self.assertRaises(ValueError):
            timesheet_lines([])

    def test_blank_worker(self):
        with self.assertRaises(ValueError):
            timesheet_lines([shift("  ", 540, 600)])

    def test_sample_schedule(self):
        shifts = load_schedule(data_file("schedule.csv"))
        lines = timesheet_lines(shifts)
        self.assertEqual(len(lines), len(
            {item.worker for item in shifts}
        ))


if __name__ == "__main__":
    unittest.main()
